import java.io.*;

public class Main {
    static String sqrtTruncated(long n, int d) {
        // Write your solution here
        return "";
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int q = (int) in.nval;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            long n = (long) in.nval;
            in.nextToken();
            int d = (int) in.nval;
            sb.append(sqrtTruncated(n, d)).append('\n');
        }
        System.out.print(sb);
    }
}

